CREATE TABLE animal_cost_entries(id uuid PRIMARY KEY,farm_id uuid NOT NULL REFERENCES farms(id),animal_id uuid NOT NULL,item_id uuid,entry_date date NOT NULL,category text NOT NULL CHECK(category IN ('Feed','Vaccination','Treatment','Breeding','Other')),description text NOT NULL,quantity numeric(18,3) NOT NULL CHECK(quantity>0),unit text NOT NULL,unit_cost numeric(18,6) NOT NULL CHECK(unit_cost>=0),total numeric(18,2) GENERATED ALWAYS AS (round(quantity*unit_cost,2)) STORED,notes text,created_at timestamptz NOT NULL DEFAULT now(),user_id uuid NOT NULL REFERENCES users(id),FOREIGN KEY(farm_id,animal_id) REFERENCES animals(farm_id,id),FOREIGN KEY(farm_id,item_id) REFERENCES inventory(farm_id,id),UNIQUE(farm_id,id));
CREATE INDEX animal_cost_entries_farm_animal_date_idx ON animal_cost_entries(farm_id,animal_id,entry_date DESC);
